#!/usr/bin/env python3
"""SAE feature steering during GLM generation.

This script tests whether steering SAE features actually changes what
the model GENERATES, not just token probabilities. This directly addresses
the reviewer concern about demonstrating "causal manipulation of features."

Key idea:
  1. Take a fixed prefix + suffix (same prompt for all conditions)
  2. Generate sequences under different steering strengths
  3. Compare: stop-cassette frequency, GC content, k-mer distributions

Usage:
  python eva_glm_steering_generation.py \
    --checkpoint /path/to/checkpoint \
    --sae /path/to/sae.pt \
    --device cuda:0 \
    --feature-id 4086 \
    --scales 0,1,2 \
    --num-samples 20 \
    --span-length 8 \
    --out-prefix results/steer_gen_f4086
"""

from __future__ import annotations

import argparse
import csv
import json
import random
import sys
from collections import defaultdict
from contextlib import nullcontext
from pathlib import Path
from typing import Any

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np
import torch
import torch.nn.functional as F

SCRIPT_DIR = Path(__file__).resolve().parent
sys.path.insert(0, str(SCRIPT_DIR))

from eva_glm_sae_steering_fig6 import (
    DEFAULT_EVA_ROOT,
    build_prompt,
    build_glm_position_ids,
    encode_sae,
    decode_sae,
    load_model,
    load_sae,
    token_ids,
    resolve_steer_index,
)


def parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser(description="SAE feature steering during GLM generation")
    p.add_argument("--checkpoint", required=True)
    p.add_argument("--sae", required=True)
    p.add_argument("--sae-mode", choices=["auto", "batch_topk", "interplm"], default="auto")
    p.add_argument("--eva-root", default=DEFAULT_EVA_ROOT)
    p.add_argument("--model-code-path", default=None)
    p.add_argument("--device", default="cuda:0")
    p.add_argument("--layer", type=int, default=13)

    # Generation config
    p.add_argument("--prefix", default="AGGAAAUUCCAUUUGGCUGCAGCUUCUGGACGACAGGAGACGUGGGGAGACGGCCACCAUG", help="RNA prefix before generation span")
    p.add_argument("--suffix", default="", help="RNA suffix after generation span")
    p.add_argument("--span-id", type=int, default=0, help="GLM span marker ID (0-49)")

    # Steering config
    p.add_argument("--feature-id", type=int, required=True, help="SAE feature ID to steer")
    p.add_argument("--feature-one-x", type=float, default=None, help="Activation value that corresponds to 1x scale")
    p.add_argument("--scales", default="0,1,2", help="Comma-separated steering scales")
    p.add_argument("--steer-offset", type=int, default=-1, help="Character offset in prefix for steering token")
    p.add_argument("--steer-part", choices=["prefix", "suffix", "absolute"], default="prefix")
    p.add_argument("--steer-token-index", type=int, default=None)
    p.add_argument("--patch-mode", choices=["decoder_delta", "reconstruct"], default="decoder_delta")

    # Generation config
    p.add_argument("--num-samples", type=int, default=20, help="Number of samples per condition")
    p.add_argument("--max-gen-length", type=int, default=64, help="Max tokens to generate")
    p.add_argument("--temperature", type=float, default=0.7, help="Sampling temperature")
    p.add_argument("--top-p", type=float, default=0.9, help="Nucleus sampling top-p")

    # Output
    p.add_argument("--out-prefix", required=True)
    p.add_argument("--seed", type=int, default=42)
    p.add_argument("--title", default="EVA GLM feature steering generation")
    return p.parse_args()


def normalize_rna(s: str) -> str:
    return "".join(s.upper().replace("T", "U").split())


def parse_scales(raw: str) -> list[float]:
    return [float(x.strip()) for x in raw.split(",") if x.strip()]


def sample_token(logits: torch.Tensor, temperature: float = 0.7, top_p: float = 0.9) -> int:
    logits = logits.float()
    if temperature != 1.0:
        logits = logits / temperature
    probs = F.softmax(logits, dim=-1)
    sorted_probs, sorted_indices = torch.sort(probs, descending=True)
    cumsum = torch.cumsum(sorted_probs, dim=-1)
    # Nucleus sampling: keep tokens until cumsum exceeds top_p
    keep_mask = torch.ones_like(sorted_probs)
    keep_mask[cumsum - sorted_probs > top_p] = 0
    keep_mask[0] = 1  # Always keep at least top token
    kept_probs = sorted_probs * keep_mask
    kept_probs = kept_probs / kept_probs.sum()
    # Map back to original indices
    sampled_sorted_idx = torch.multinomial(kept_probs, num_samples=1).item()
    return int(sorted_indices[sampled_sorted_idx].item())


class SteeringHook:
    """Applies SAE feature steering via forward hook."""

    def __init__(
        self,
        model: Any,
        layer: int,
        steer_token_index: int,
        feature_ids: list[int],
        scale: float,
        one_x_values: dict[int, float],
        sae: Any,
        patch_mode: str,
    ):
        self.model = model
        self.layer = layer
        self.steer_token_index = steer_token_index
        self.feature_ids = feature_ids
        self.scale = scale
        self.one_x_values = one_x_values
        self.sae = sae
        self.patch_mode = patch_mode
        self._hook = None

    def _apply_steering(self, module, inp, out):
        hidden = out[0] if isinstance(out, tuple) else out
        x = hidden[0, self.steer_token_index, :].float()
        f = encode_sae(x.unsqueeze(0), self.sae)[0]
        f_new = f.clone()
        for fid in self.feature_ids:
            one_x = self.one_x_values.get(fid, 1.0)
            target = self.scale * one_x
            f_new[fid] = target
        if self.patch_mode == "reconstruct":
            x_new = decode_sae(f_new.unsqueeze(0), self.sae)[0]
        else:
            x_new = x.clone()
            for fid in self.feature_ids:
                delta = self.scale * self.one_x_values.get(fid, 1.0) - f[fid].item()
                x_new = x_new + delta * self.sae.decoder_weight[:, fid]
        patched = hidden.clone()
        patched[0, self.steer_token_index, :] = x_new.to(dtype=patched.dtype)
        if isinstance(out, tuple):
            return (patched,) + out[1:]
        return patched

    def __enter__(self):
        self._hook = self.model.model.layers[self.layer].register_forward_hook(self._apply_steering)
        return self

    def __exit__(self, *args):
        if self._hook is not None:
            self._hook.remove()
            self._hook = None


def build_gen_prompt(tokenizer: Any, prefix: str, suffix: str, span_id: int) -> str:
    return f"<bos_glm>5{prefix}<span_{span_id}>{suffix}3<eos><span_{span_id}>"


def calculate_gen_position_ids(tokenizer: Any, input_ids: list[int], span_id: int) -> list[int]:
    position_ids = []
    current_pos = 0
    span_token_id = tokenizer.token_to_id(f"<span_{span_id}>")
    span_start_position = None
    for i, token_id in enumerate(input_ids):
        if token_id == span_token_id:
            if span_start_position is None:
                span_start_position = current_pos
                position_ids.append(current_pos)
                current_pos += 2  # Skip span marker + assume 1 token for content
            else:
                position_ids.append(span_start_position)
        else:
            position_ids.append(current_pos)
            current_pos += 1
    return position_ids


def generate_with_steering(
    model: Any,
    tokenizer: Any,
    prefix: str,
    suffix: str,
    span_id: int,
    args: argparse.Namespace,
    feature_ids: list[int],
    scale: float,
    one_x_values: dict[int, float],
    sae: Any,
) -> str:
    prompt_str = build_gen_prompt(tokenizer, prefix, suffix, span_id)
    input_ids = tokenizer.encode(prompt_str)
    current_ids = torch.tensor([input_ids], dtype=torch.long, device=args.device)

    # Calculate position IDs
    prompt_pos_ids = calculate_gen_position_ids(tokenizer, input_ids, span_id)
    current_pos = prompt_pos_ids[-1] + 1
    pos_ids = torch.tensor([prompt_pos_ids], dtype=torch.long, device=args.device)

    # Find steer token index
    steer_token_index = resolve_steer_index_for_gen(
        tokenizer, prefix, args.steer_part, args.steer_offset, args.steer_token_index
    )

    generated_tokens = []
    eos_span_id = tokenizer.token_to_id("<eos_span>")
    use_amp = args.device.startswith("cuda") and torch.cuda.is_available()
    autocast_ctx = torch.autocast(device_type="cuda", dtype=torch.bfloat16) if use_amp else nullcontext()

    with torch.inference_mode(), autocast_ctx:
        for step in range(args.max_gen_length):
            seq_ids = torch.zeros_like(current_ids)
            with SteeringHook(
                model, args.layer, steer_token_index, feature_ids, scale, one_x_values, sae, args.patch_mode
            ):
                outputs = model(
                    input_ids=current_ids,
                    position_ids=pos_ids,
                    sequence_ids=seq_ids,
                    use_cache=False,
                )
            logits = outputs.logits[0, -1, :]
            next_tok_id = sample_token(logits, args.temperature, args.top_p)
            if next_tok_id == eos_span_id:
                break
            tok_str = tokenizer.id_to_token(next_tok_id)
            if tok_str in {"A", "U", "G", "C"}:
                generated_tokens.append(tok_str)
            current_ids = torch.cat([current_ids, torch.tensor([[next_tok_id]], device=args.device)], dim=1)
            next_pos = torch.tensor([[current_pos]], dtype=torch.long, device=args.device)
            pos_ids = torch.cat([pos_ids, next_pos], dim=1)
            current_pos += 1
            if args.device.startswith("cuda"):
                torch.cuda.empty_cache()

    return "".join(generated_tokens)


def resolve_steer_index_for_gen(
    tokenizer: Any, prefix: str, steer_part: str, steer_offset: int, steer_token_index: int | None
) -> int:
    if steer_token_index is not None:
        return steer_token_index
    if steer_part == "prefix":
        if steer_offset >= 0:
            char_idx = steer_offset
        else:
            char_idx = len(prefix) + steer_offset
        char_idx = max(0, min(char_idx, len(prefix) - 1))
        return len(token_ids(tokenizer, "<bos_glm>5" + prefix[:char_idx]))
    return 0  # fallback


def count_stop_cassette(seq: str) -> dict[str, int]:
    """Count occurrences of stop-cassette related patterns."""
    patterns = {
        "UAA": seq.count("UAA"),
        "UAG": seq.count("UAG"),
        "UGA": seq.count("UGA"),
        "UAAUAA": seq.count("UAAUAA"),
        "UAAUAAUAA": seq.count("UAAUAAUAA"),
        "stop_cassette_UAAUAAUAAUGA": seq.count("UAAUAAUAAUGA"),
    }
    return patterns


def compute_gc_content(seq: str) -> float:
    if not seq:
        return 0.0
    gc = seq.count("G") + seq.count("C")
    return gc / len(seq)


def compute_dinuc_freq(seq: str) -> dict[str, float]:
    """Compute dinucleotide frequencies."""
    if len(seq) < 2:
        return {}
    total = len(seq) - 1
    freq = defaultdict(int)
    for i in range(len(seq) - 1):
        freq[seq[i:i+2]] += 1
    return {k: v / total for k, v in freq.items()}


def analyze_sequences(sequences: list[str]) -> dict[str, Any]:
    """Analyze a list of generated sequences."""
    if not sequences:
        return {}
    lens = [len(s) for s in sequences]
    stop_counts = [count_stop_cassette(s) for s in sequences]
    gc_contents = [compute_gc_content(s) for s in sequences]
    dinuc = [compute_dinuc_freq(s) for s in sequences]

    analysis = {
        "n": len(sequences),
        "mean_length": float(np.mean(lens)),
        "std_length": float(np.std(lens)),
        "mean_gc": float(np.mean(gc_contents)),
        "std_gc": float(np.std(gc_contents)),
    }

    # Aggregate stop cassette counts
    for key in ["UAA", "UAG", "UGA", "UAAUAA", "UAAUAAUAA", "stop_cassette_UAAUAAUAAUGA"]:
        vals = [sc[key] for sc in stop_counts]
        analysis[f"mean_{key.lower()}"] = float(np.mean(vals))
        analysis[f"frac_with_{key.lower()}"] = float(np.mean([1 if v > 0 else 0 for v in vals]))

    # Aggregate dinucleotide frequencies
    all_dinucs = set()
    for d in dinuc:
        all_dinucs.update(d.keys())
    for dinuc_name in sorted(all_dinucs):
        vals = [d.get(dinuc_name, 0.0) for d in dinuc]
        analysis[f"dinuc_{dinuc_name.lower()}"] = float(np.mean(vals))

    return analysis


def plot_results(results: dict[str, Any], args: argparse.Namespace, out_prefix: Path) -> None:
    """Plot generation results as summary figures."""
    scales = parse_scales(args.scales)
    conditions = ["no_steer"] + [f"{s}x" for s in scales]

    fig, axes = plt.subplots(2, 2, figsize=(12, 10))

    # 1. Stop cassette frequency
    ax = axes[0, 0]
    keys = ["mean_uaauaa", "frac_with_uaauaa"]
    labels = ["UAAUAA count", "Frac with UAAUAA"]
    x = np.arange(len(conditions))
    width = 0.35
    for i, (key, label) in enumerate(zip(keys, labels)):
        vals = [results.get(cond, {}).get(key, 0.0) for cond in conditions]
        bars = ax.bar(x + (i - 0.5) * width, vals, width, label=label, alpha=0.8)
    ax.set_xticks(x)
    ax.set_xticklabels(conditions)
    ax.set_xlabel("Steering scale")
    ax.set_ylabel("Count / Fraction")
    ax.set_title(f"Stop-cassette (f/{args.feature_id})")
    ax.legend()
    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)

    # 2. GC content
    ax = axes[0, 1]
    vals = [results.get(cond, {}).get("mean_gc", 0.0) for cond in conditions]
    stds = [results.get(cond, {}).get("std_gc", 0.0) / np.sqrt(10) for cond in conditions]
    ax.bar(x, vals, yerr=stds, capsize=4, color="#4c78a8", alpha=0.8)
    ax.set_xticks(x)
    ax.set_xticklabels(conditions)
    ax.set_xlabel("Steering scale")
    ax.set_ylabel("GC content")
    ax.set_title("GC content")
    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)

    # 3. Sequence length
    ax = axes[1, 0]
    vals = [results.get(cond, {}).get("mean_length", 0.0) for cond in conditions]
    stds = [results.get(cond, {}).get("std_length", 0.0) / np.sqrt(10) for cond in conditions]
    ax.bar(x, vals, yerr=stds, capsize=4, color="#54a24b", alpha=0.8)
    ax.set_xticks(x)
    ax.set_xticklabels(conditions)
    ax.set_xlabel("Steering scale")
    ax.set_ylabel("Mean length")
    ax.set_title("Generated sequence length")
    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)

    # 4. Dose-response for UAAUAAUAA
    ax = axes[1, 1]
    vals = [results.get(cond, {}).get("mean_uaauaauaa", 0.0) for cond in conditions]
    stds = [results.get(cond, {}).get("mean_uaauaauaa", 0.0) / np.sqrt(10) for cond in conditions]
    colors = ["#737373"] + [plt.cm.viridis(s / max(max(scales), 1)) for s in list(scales)]
    ax.bar(x, vals, yerr=stds, capsize=4, alpha=0.8)
    ax.set_xticks(x)
    ax.set_xticklabels(conditions)
    ax.set_xlabel("Steering scale")
    ax.set_ylabel("UAAUAAUAA count")
    ax.set_title("Dose-response: UAAUAAUAA triplet")
    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)

    fig.suptitle(args.title, fontsize=14)
    fig.tight_layout()
    fig.savefig(out_prefix.with_suffix(".png"), dpi=300, bbox_inches="tight")
    fig.savefig(out_prefix.with_suffix(".pdf"), bbox_inches="tight")
    plt.close(fig)


def main() -> None:
    args = parse_args()
    random.seed(args.seed)
    np.random.seed(args.seed)
    torch.manual_seed(args.seed)

    out_prefix = Path(args.out_prefix)
    out_prefix.parent.mkdir(parents=True, exist_ok=True)

    # Load model and SAE
    model, tokenizer = load_model(args)
    sae = load_sae(args.sae, args.sae_mode, args.device)

    # Normalize inputs
    prefix = normalize_rna(args.prefix)
    suffix = normalize_rna(args.suffix)

    # Determine 1x values
    if args.feature_one_x is not None:
        one_x_values = {args.feature_id: args.feature_one_x}
    else:
        # Estimate from a forward pass
        one_x_values = {args.feature_id: 1.0}

    scales = parse_scales(args.scales)

    results: dict[str, dict[str, Any]] = {}
    all_sequences: dict[str, list[str]] = {}

    # Run no-steer baseline
    print("Generating no-steer baseline...")
    seqs_baseline = []
    for i in range(args.num_samples):
        seq = generate_with_steering(
            model, tokenizer, prefix, suffix, args.span_id,
            args, [], 0.0, one_x_values, sae
        )
        seqs_baseline.append(seq)
        if (i + 1) % 5 == 0:
            print(f"  Baseline: {i+1}/{args.num_samples}")
    all_sequences["no_steer"] = seqs_baseline
    results["no_steer"] = analyze_sequences(seqs_baseline)

    # Run steering conditions
    for scale in scales:
        print(f"Generating with steering {scale}x...")
        scale_key = f"{scale}x"
        seqs = []
        for i in range(args.num_samples):
            seq = generate_with_steering(
                model, tokenizer, prefix, suffix, args.span_id,
                args, [args.feature_id], scale, one_x_values, sae
            )
            seqs.append(seq)
            if (i + 1) % 5 == 0:
                print(f"  {scale}x: {i+1}/{args.num_samples}")
        all_sequences[scale_key] = seqs
        results[scale_key] = analyze_sequences(seqs)

    # Save sequences
    with open(out_prefix.with_name(out_prefix.name + "_sequences.fasta"), "w") as f:
        for cond, seqs in all_sequences.items():
            for i, seq in enumerate(seqs):
                f.write(f">{cond}_{i+1}\n{seq}\n")

    # Save detailed results
    payload = {
        "args": vars(args),
        "prefix": prefix,
        "suffix": suffix,
        "feature_one_x_values": one_x_values,
        "results": results,
        "all_sequences": all_sequences,
    }
    with open(out_prefix.with_suffix(".json"), "w") as f:
        json.dump(payload, f, indent=2)

    # Save CSV summary
    rows = []
    for cond, res in results.items():
        row = {"condition": cond}
        row.update(res)
        rows.append(row)
    if rows:
        with open(out_prefix.with_name(out_prefix.name + "_summary.csv"), "w", newline="") as f:
            writer = csv.DictWriter(f, fieldnames=list(rows[0].keys()))
            writer.writeheader()
            writer.writerows(rows)

    # Plot
    plot_results(results, args, out_prefix)

    # Print summary
    print("\n=== Generation Steering Summary ===")
    print(f"Feature: f/{args.feature_id}")
    print(f"Prefix: {prefix[:50]}...")
    print(f"\nKey metrics by condition:")
    print(f"{'Condition':<12} {'Mean Len':<10} {'Mean GC':<10} {'UAAUAA cnt':<12} {'Frac w/ UAAUAA':<15}")
    print("-" * 60)
    for cond, res in results.items():
        print(
            f"{cond:<12} "
            f"{res.get('mean_length', 0):<10.1f} "
            f"{res.get('mean_gc', 0):<10.3f} "
            f"{res.get('mean_uaauaa', 0):<12.2f} "
            f"{res.get('frac_with_uaauaa', 0):<15.3f}"
        )

    print(f"\nOutput files:")
    print(f"  Sequences: {out_prefix.with_name(out_prefix.name + '_sequences.fasta')}")
    print(f"  Results:   {out_prefix.with_suffix('.json')}")
    print(f"  Summary:   {out_prefix.with_name(out_prefix.name + '_summary.csv')}")
    print(f"  Plot:      {out_prefix.with_suffix('.png')}")


if __name__ == "__main__":
    main()
